// --- lib_rl.FDb.cand.Find
// Look up row by row id. Return NULL if out of range
inline algo::cstring* lib_rl::cand_Find(u64 t) {
    algo::cstring *retval = NULL;
    if (LIKELY(u64(t) < u64(_db.cand_n))) {
        u64 x = t + 1;
        u64 bsr   = algo::u64_BitScanReverse(x);
        u64 base  = u64(1)<<bsr;
        u64 index = x-base;
        retval = &_db.cand_lary[bsr][index];
    }
    return retval;
}

